ALTER TABLE "match_participants" ADD CONSTRAINT "match_participants_attendance_evidence_ck" CHECK (("match_participants"."attendance" is null and "match_participants"."attendance_confirmed_at" is null and "match_participants"."attendance_confirmed_by_player_id" is null) or ("match_participants"."status" = 'CONFIRMED' and "match_participants"."attendance" is not null and "match_participants"."attendance_confirmed_at" is not null and "match_participants"."attendance_confirmed_by_player_id" is not null));